import csv
import io


def _parse_row(row):
    sku = row.get('sku')
    name = row.get('name')
    qty = row.get('qty')
    if not isinstance(sku, str) or not isinstance(name, str) or not isinstance(qty, str):
        raise ValueError('invalid row: missing field')
    sku = sku.strip()
    name = name.strip()
    qty = qty.strip()
    if not sku or not name or not qty or not all('0' <= c <= '9' for c in qty):
        raise ValueError('invalid row: %r' % (row,))
    return {'sku': sku, 'name': name, 'qty': int(qty)}


def import_text(text, store, dry_run=False):
    # Validate every row before committing any changes.
    items = [_parse_row(row) for row in csv.DictReader(io.StringIO(text))]

    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item in items:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
        if not dry_run:
            store.put(item)
    return result

